// ── Runtime lang state ──────────────────────────────────────────────────────
let _currentLang = (() => {
  try { return localStorage.getItem('iw_lang') || 'en' } catch { return 'en' }
})()

const _listeners = new Set()

export function getLang()  { return _currentLang }

export function setLang(code) {
  _currentLang = code
  try { localStorage.setItem('iw_lang', code) } catch { /* */ }
  _listeners.forEach(fn => fn(code))
}

export function subscribeLang(fn) {
  _listeners.add(fn)
  return () => _listeners.delete(fn)
}

/** Translate a key. Falls back to English, then to the key itself. */
export function t(key, lang) {
  const use = lang || _currentLang
  const row = TRANSLATIONS[key]
  if (!row) return key
  return row[use] || row['en'] || key
}
